package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaDecimalPowerPlaceTest {
 @Test public void normalNaSixCoversAllPowersPrecisionAndSelectedPlaces(){var pack=GlobalCurriculum.packs("NA").stream().filter(v->v.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();Generator g=new Generator(new Random(294));for(String id:List.of(DecimalPowerTen.MUL,DecimalPowerTen.DIV)){assertTrue(pack.inGrade(id,6));var l=GlobalCurriculum.limits(pack.id,id,6);assertEquals(1595700,DecimalPowerTen.count(id,l));List<String> recent=new ArrayList<>();Set<Integer> powers=new HashSet<>(),precision=new HashSet<>(),positions=new HashSet<>();boolean zero=false;for(int i=0;i<500;i++){Question q=g.next(id,recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=DecimalPowerPlaceRelations.read(q);assertNotNull(v);powers.add(v.power());precision.add(new BigDecimal(v.digit().raw()).scale());positions.add(v.digit().position());zero|=v.digit().digit()==0;BigDecimal x=new BigDecimal(v.digit().raw()),factor=BigDecimal.valueOf(v.power()),before=BigDecimal.valueOf(v.digit().digit()).movePointLeft(v.digit().position());List<String> expected=List.of((v.multiply()?x.multiply(factor):x.divide(factor)).toPlainString(),before.toPlainString(),(v.multiply()?before.multiply(factor):before.divide(factor)).toPlainString());Arrays.fill(q.answers,"poison");q.expression="poison";assertTrue(new Checker().check(q,List.of(),expected).correct());assertEquals(10,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(Set.of(10,100,1000),powers);assertEquals(Set.of(1,2,3),precision);assertEquals(Set.of(-1,0,1,2,3),positions);assertTrue(zero);}}
 @Test public void thousandthsCrossZerosAndWholePlacesWithIndependentFieldErrors(){Question q=DecimalPowerPlaceRelations.make(DecimalPowerTen.DIV,"0.007",1000,3);q.answers=new String[]{"poison","poison","poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of("0.000007","0.007","0.000007")).correct());assertEquals(1,new Checker().check(q,List.of(),List.of("0.000007","7","0.000007")).index);assertEquals(2,new Checker().check(q,List.of(),List.of("0.000007","0.007","0.007")).index);q=DecimalPowerPlaceRelations.make(DecimalPowerTen.MUL,"99.999",1000,-1);assertTrue(new Checker().check(q,List.of(),List.of("99999","90","90000")).correct());q=DecimalPowerPlaceRelations.make(DecimalPowerTen.DIV,"1.00",100,2);assertTrue(new Checker().check(q,List.of(),List.of("0.01","0","0")).correct());}
 @Test public void publicHelpUsesDigitDirectionAndUnitsWithoutTransferringAnswers(){Question q=DecimalPowerPlaceRelations.make(DecimalPowerTen.DIV,"37.405",1000,3);q.answers=new String[]{"poison","poison","poison"};HelpPlan h=HelpPlan.forQuestion(q);List<String> entries=List.of("37.405","1000","3","right","5","0.001","0.005","0.000001","0.000005","0.037405");assertEquals(entries.size(),h.size());for(int i=0;i<entries.size();i++)assertTrue("frame "+i,h.step(i).accepts(entries.get(i)));assertFalse(h.canTransfer());assertFalse(h.step(3).accepts("left"));assertEquals(300000,DecimalPowerTen.count(DecimalPowerTen.MUL,GlobalCurriculum.limits("england-primary-2021-v1",DecimalPowerTen.MUL,6)));}
}
